699	static void sunxi_codec_init(struct snd_codec *codec)
700	{
701		struct sunxi_codec_info *sunxi_codec = codec->private_data;
702		struct sunxi_codec_param *param = &sunxi_codec->param;
703		struct alg_cfg_reg_domain domain_1bdrc = {
704			.reg_base = (void *)SUNXI_CODEC_BASE_ADDR,
705			.reg_min = SUNXI_DAC_DAP_CTL,
706			.reg_max = SUNXI_DAC_DRC_HPFLGAIN,
707		};
708	
709		/* get chp version */
710		sunxi_codec->chip_ver = hal_efuse_get_chip_ver();
711	
712		/* In order to ensure that the ADC sampling is normal,
713		 * the A chip SOC needs to always open HPLDO and RMC_EN
714		 */
715		if (sunxi_codec->chip_ver == CHIP_VER_A) {
716			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
717				(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
718			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
719				(0x1<<RMCEN), (0x1<<RMCEN));
720		} else {
721			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
722				(0x1<<HPLDO_EN), (0x0<<HPLDO_EN));
723			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
724				(0x1<<RMCEN), (0x0<<RMCEN));
725		}
726	
727		/* Disable HPF(high passed filter) */
728		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
729				(1 << HPF_EN), (0x0 << HPF_EN));
730	
731		if (param->rx_sync_en) {
732			/* disabled ADCFDT */
733			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
734					(0x1 << ADCDFEN), (0x0 << ADCDFEN));
735			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
736					(0x3 << ADCFDT), (0x2 << ADCFDT));
737			/* RX_SYNC_EN */
738			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC, 1 << RX_SYNC_EN, 0 << RX_SYNC_EN);
739		} else {
740			/* Enable ADCFDT to overcome niose at the beginning */
741			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
742					(0x1 << ADCDFEN), (0x1 << ADCDFEN));
743			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
744					(0x3 << ADCFDT), (0x2 << ADCFDT));
745		}
746	
747		/* init the mic pga and vol params */
748		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
749				0x1F << LINEOUT_VOL,
750				param->lineout_vol << LINEOUT_VOL);
751		snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
752				0x7 << HP_GAIN,
753				param->hpout_vol << HP_GAIN);
754	
755		/* DAC_VOL_SEL enable */
756		snd_codec_update_bits(codec, SUNXI_DAC_VOL_CTL,
757				(0x1 << DAC_VOL_SEL), (0x1 << DAC_VOL_SEL));
758		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
759				0x3F << DVOL,
760				param->digital_vol << DVOL);
761	
762		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
763				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN),
764				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN));
765	
766		snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
767				0x1F << ADC_PGA_GAIN_CTL,
768				param->mic1gain << ADC_PGA_GAIN_CTL);
769	
770		snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
771				0x1F << ADC_PGA_GAIN_CTL,
772				param->mic2gain << ADC_PGA_GAIN_CTL);
773	
774		snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
775				0x1F << ADC_PGA_GAIN_CTL,
776				param->mic3gain << ADC_PGA_GAIN_CTL);
777	
778	#ifdef SUNXI_CODEC_DAP_ENABLE
779		if (param->dacdrc_cfg || param->dachpf_cfg) {
780			snd_codec_update_bits(codec, SUNXI_DAC_DAP_CTL,
781					(0x1 << DDAP_EN), (0x1 << DDAP_EN));
782		}
783	
784		if (param->adcdrc_cfg || param->adchpf_cfg) {
785			snd_codec_update_bits(codec, SUNXI_ADC_DAP_CTL,
786					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN),
787					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN));
788		}
789	
790		if (param->adcdrc_cfg) {
791			adcdrc_config(codec);
792			adcdrc_enable(codec, 1);
793		}
794		if (param->adchpf_cfg) {
795			adchpf_config(codec);
796			adchpf_enable(codec, 1);
797		}
798		if (param->dacdrc_cfg) {
799			dacdrc_config(codec);
800			dacdrc_enable(codec, 1);
801		}
802		if (param->dachpf_cfg) {
803			dachpf_config(codec);
804			dachpf_enable(codec, 1);
805		}
806	#endif
807	
808		sunxi_alg_cfg_domain_set(&domain_1bdrc, SUNXI_ALG_CFG_DOMAIN_1BDRC);
809	}
