874	static void sunxi_codec_playback_hp_route(struct snd_codec *codec, int spk, int onoff)
875	{
876		struct sunxi_codec_info *sunxi_codec = codec->private_data;
877	
878		if (onoff) {
879			if (sunxi_codec->chip_ver == CHIP_VER_A) {
880				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
881						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
882						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN));
883				/* ramp out enable */
884				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
885						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
886						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH));
887				/* digital DAC enable */
888				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
889						(0x1<<EN_DAC), (0x1<<EN_DAC));
890				hal_msleep(5);
891				/* analog DAC enable and unmute */
892				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
893						(0x1<<DACLEN) | (0x1<<DACREN) |
894						(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
895						(0x1<<DACLEN) | (0x1<<DACREN) |
896						(0x1<<DACLMUTE) | (0x1<<DACRMUTE));
897				/* HEADPONEOUT */
898				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
899					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN),
900					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN));
901				/* Playback on */
902				snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
903					(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
904			} else {
905				/* digital DAC enable */
906				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
907						(0x1<<EN_DAC), (0x1<<EN_DAC));
