960	static void sunxi_codec_playback_lineout_route(struct snd_codec *codec, int spk, int onoff)
961	{
962		struct sunxi_codec_info *sunxi_codec = codec->private_data;
963		struct sunxi_codec_param *param = &sunxi_codec->param;
964	
965		if (onoff) {
966			/* digital DAC enable */
967			snd_codec_update_bits(codec, SUNXI_DAC_DPC,
968					(0x1<<EN_DAC), (0x1<<EN_DAC));
969			hal_msleep(5);
970			/* analog DAC enable */
971			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
972					(0x1<<DACLEN) | (0x1<<DACREN),
973					(0x1<<DACLEN) | (0x1<<DACREN));
974			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
975					(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
976					(0x1<<DACLMUTE) | (0x1<<DACRMUTE));
977			if (sunxi_codec->chip_ver != CHIP_VER_A) {
978				uint32_t reg_val;
979				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
980				if(!(reg_val & (0x1 << RDEN)))
981					snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
982							0x1<<RDEN, 0x1<<RDEN);
983			}
984			snd_codec_update_bits(codec, SUNXI_DAC_REG,
985					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
986					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN));
987			if (spk) {
988				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
989				hal_gpio_set_data(param->gpio_spk, param->pa_level);
990				hal_msleep(param->pa_msleep_time);
991			}
992		} else {
993			if (spk) {
994				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
995				hal_gpio_set_data(param->gpio_spk, !param->pa_level);
996			}
997			/* analog DAC */
998			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
999					(0x1<<DACLEN) | (0x1<<DACREN),
1000					(0x0<<DACLEN) | (0x0<<DACREN));
1001			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
1002					(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
1003					(0x0<<DACLMUTE) | (0x0<<DACRMUTE));
1004			/* digital DAC enable */
1005			snd_codec_update_bits(codec, SUNXI_DAC_DPC,
1006					(0x1<<EN_DAC), (0x0<<EN_DAC));
1007			snd_codec_update_bits(codec, SUNXI_DAC_REG,
1008					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
1009					(0x0<<LINEOUTL_EN) | (0x0<<LINEOUTR_EN));
1010			if (sunxi_codec->chip_ver != CHIP_VER_A) {
1011				uint32_t reg_val;
1012				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
1013				if(!(reg_val & (0x1 << RDEN)))
1014					snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
1015							0x1<<RDEN, 0x0<<RDEN);
1016			}
1017		}
1018	
1019	}
