static int sunxi_codec_ramp_update_bits(struct snd_codec *codec,
					uint32_t mask, uint32_t value)
{
	uint32_t old;
	uint32_t new;
	int ret;

	if (mask & RAMP_W1C_MASK) {
		snd_err("ramp update contains W1C bits: mask=0x%08x\n", mask);
		return -1;
	}

	old = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
	new = ((old & ~mask) | (value & mask)) & ~RAMP_W1C_MASK;
	if ((old & mask) == (new & mask))
		return 0;

	ret = snd_codec_write(codec, SUNXI_RAMP_ANA_CTL, new);
	if (ret)
		snd_err("ramp register write failed: ret=%d value=0x%08x\n",
			ret, new);

	return ret;
}

