1047	static int sunxi_codec_dapm_control(struct snd_pcm_substream *substream,
1048					struct snd_dai *dai, int onoff)
1049	{
1050		struct snd_codec *codec = dai->component;
1051		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1052		struct sunxi_codec_param *param = &sunxi_codec->param;
1053	
