1055			return 0;
1056		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1057			/*
1058			 * Playback:
1059			 * Playback --> DAC --> DAC_DIFFER --> LINEOUT/HPOUT + (External Speaker)
1060			 */
1061	
1062			switch (param->pb_audio_route) {
1063			case PB_AUDIO_ROUTE_LINEOUT_SPK:
1064				sunxi_codec_playback_lineout_route(codec, 1, onoff);
1065				break;
1066			case PB_AUDIO_ROUTE_HEADPHONE_SPK:
1067				sunxi_codec_playback_hp_route(codec, 1, onoff);
1068				break;
1069			case PB_AUDIO_ROUTE_LINEOUT:
