4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <fcntl.h>
9	#include <stdint.h>
10	#include <stdio.h>
11	#include <string.h>
12	#include <unistd.h>
13	
14	#include "voice_recognizer.h"
15	
16	#define VOICE_DEMO_FRAME_SAMPLES        320
17	#define VOICE_DEMO_MIN_ACTIVE_FRAMES    4
18	#define VOICE_DEMO_MIN_RMS              350
19	#define VOICE_DEMO_MIN_PEAK             900
20	
21	struct voice_demo_metrics_s
22	{
23	  uint32_t active_frames;
24	  uint32_t frames;
25	  uint32_t peak;
26	};
27	
28	static void voice_demo_measure(FAR const int16_t *samples, size_t count,
29	                               FAR struct voice_demo_metrics_s *metrics)
30	{
31	  size_t offset;
32	
33	  for (offset = 0; offset < count; offset += VOICE_DEMO_FRAME_SAMPLES)
34	    {
35	      size_t frame_count = count - offset;
36	      uint64_t energy = 0;
37	      uint32_t frame_peak = 0;
38	      size_t i;
39	
40	      if (frame_count > VOICE_DEMO_FRAME_SAMPLES)
41	        {
42	          frame_count = VOICE_DEMO_FRAME_SAMPLES;
43	        }
44	
45	      for (i = 0; i < frame_count; i++)
46	        {
47	          int32_t sample = samples[offset + i];
48	          uint32_t magnitude = sample < 0 ? -sample : sample;
49	
50	          if (magnitude > frame_peak)
51	            {
52	              frame_peak = magnitude;
53	            }
54	
55	          energy += (uint64_t)(sample * sample);
56	        }
57	
58	      if (frame_peak > metrics->peak)
59	        {
60	          metrics->peak = frame_peak;
61	        }
62	
63	      if (frame_peak >= VOICE_DEMO_MIN_PEAK &&
64	          energy / frame_count >= VOICE_DEMO_MIN_RMS * VOICE_DEMO_MIN_RMS)
65	        {
66	          metrics->active_frames++;
67	        }
68	
69	      metrics->frames++;
70	    }
71	}
72	
73	static int voice_demo_result(FAR const struct voice_demo_metrics_s *metrics,
74	                             FAR uint16_t *score)
75	{
76	  if (metrics->frames == 0 ||
77	      metrics->active_frames < VOICE_DEMO_MIN_ACTIVE_FRAMES ||
78	      metrics->peak < VOICE_DEMO_MIN_PEAK)
79	    {
80	      *score = 0;
81	      return -ENODATA;
82	    }
83	
84	  *score = metrics->active_frames * 1000 / metrics->frames;
85	  return OK;
86	}
87	
88	static int voice_demo_analyze(FAR const int16_t *samples, size_t count,
89	                              FAR uint16_t *score)
90	{
91	  struct voice_demo_metrics_s metrics = {0};
92	
93	  if (samples == NULL || score == NULL || count == 0)
94	    {
95	      return -EINVAL;
96	    }
97	
98	  voice_demo_measure(samples, count, &metrics);
99	  return voice_demo_result(&metrics, score);
100	}
101	
102	int voice_recognizer_demo_recognize(
103	  FAR const char *pcm_path,
104	  FAR struct voice_recognition_result_s *result)
105	{
106	  int16_t samples[VOICE_DEMO_FRAME_SAMPLES * 4];
107	  struct voice_demo_metrics_s metrics = {0};
108	  ssize_t nread;
109	  int fd;
110	
111	  if (pcm_path == NULL || result == NULL)
112	    {
113	      return -EINVAL;
114	    }
115	
116	  memset(result, 0, sizeof(*result));
117	  fd = open(pcm_path, O_RDONLY | O_CLOEXEC);
118	  if (fd < 0)
119	    {
120	      return -errno;
121	    }
122	
123	  while ((nread = read(fd, samples, sizeof(samples))) > 0)
124	    {
125	      voice_demo_measure(samples, nread / sizeof(samples[0]), &metrics);
126	    }
127	
128	  if (nread < 0)
129	    {
130	      int ret = -errno;
131	      close(fd);
132	      return ret;
133	    }
134	
135	  close(fd);
136	  if (voice_demo_result(&metrics, &result->score) < 0)
137	    {
138	      result->command = VOICE_COMMAND_UNKNOWN;
139	      return -ENODATA;
140	    }
141	
142	  result->command = VOICE_COMMAND_QUERY_TEMPERATURE;
143	  result->semantic_verified = false;
144	  return OK;
145	}
146	
147	int voice_recognizer_demo_selftest(void)
148	{
149	  int16_t silence[VOICE_DEMO_FRAME_SAMPLES * 5];
150	  int16_t speech[VOICE_DEMO_FRAME_SAMPLES * 5];
151	  uint16_t score;
152	  size_t i;
153	
154	  memset(silence, 0, sizeof(silence));
155	  for (i = 0; i < sizeof(speech) / sizeof(speech[0]); i++)
156	    {
157	      speech[i] = (i & 1) == 0 ? 1200 : -1200;
158	    }
159	
160	  if (voice_demo_analyze(silence,
161	                         sizeof(silence) / sizeof(silence[0]), &score) >= 0 ||
162	      voice_demo_analyze(speech,
163	                         sizeof(speech) / sizeof(speech[0]), &score) < 0 ||
164	      score != 1000)
165	    {
166	      return -EINVAL;
167	    }
168	
169	  return OK;
170	}
