26	#define AUDIO_SERVICE_CAPTURE_CHANNELS  1
27	#define AUDIO_SERVICE_PLAY_CHANNELS     2
28	#define AUDIO_SERVICE_BITS_PER_SAMPLE   16
29	#define AUDIO_SERVICE_SAMPLE_RATE       16000
30	#define AUDIO_SERVICE_CAPTURE_CHMAP     1
31	#define AUDIO_SERVICE_PLAY_CHMAP        3
32	#define AUDIO_SERVICE_POLL_MS           20
33	#define AUDIO_SERVICE_VOLUME_SCALE      10
34	
35	static void audio_service_publish(FAR struct audio_service_s *service,
36	                                  uint32_t operation,
37	                                  enum audio_service_state_e state,
38	                                  enum audio_service_error_e error)
39	{
40	  pthread_mutex_lock(&service->lock);
41	  if (service->worker_active && service->active_operation == operation &&
42	      service->cancelled_operation != operation)
43	    {
44	      service->state = state;
45	      service->error = error;
46	      if (state == AUDIO_SERVICE_ERROR)
47	        {
48	          service->outcome = AUDIO_SERVICE_OUTCOME_FAILED;
49	        }
50	
51	      service->sequence++;
52	    }
53	
54	  pthread_mutex_unlock(&service->lock);
55	}
56	
57	static bool audio_service_cancelled(FAR struct audio_service_s *service,
58	                                    uint32_t operation)
59	{
60	  bool cancelled;
61	
62	  pthread_mutex_lock(&service->lock);
63	  cancelled = service->shutdown_requested || !service->worker_active ||
64	              service->active_operation != operation ||
65	              service->cancelled_operation == operation;
66	  pthread_mutex_unlock(&service->lock);
67	  return cancelled;
68	}
69	
70	struct audio_service_cancel_context_s
71	{
72	  FAR struct audio_service_s *service;
73	  uint32_t operation;
74	};
75	
76	static bool audio_service_reply_cancel(FAR void *arg)
77	{
78	  FAR struct audio_service_cancel_context_s *context = arg;
79	
80	  return audio_service_cancelled(context->service, context->operation);
81	}
82	
83	static void audio_service_finish_operation(
84	  FAR struct audio_service_s *service, uint32_t operation,
85	  enum audio_service_outcome_e outcome)
86	{
87	  pthread_mutex_lock(&service->lock);
88	  if (service->worker_active && service->active_operation == operation)
89	    {
90	      service->error = AUDIO_SERVICE_ERROR_NONE;
91	      service->outcome = outcome;
92	      service->sequence++;
93	      pthread_cond_signal(&service->cond);
94	    }
95	
96	  pthread_mutex_unlock(&service->lock);
97	}
98	
99	static int audio_service_capture(FAR struct audio_service_s *service,
100	                                 uint32_t generation)
101	{
102	  struct timespec delay;
103	  uint32_t elapsed;
104	  int ret;
105	
106	  service->recorder = nxrecorder_create();
107	  if (service->recorder == NULL)
108	    {
109	      return -ENOMEM;
110	    }
111	
112	  ret = nxrecorder_setdevice(service->recorder,
113	                             service->config.capture_device);
114	  if (ret < 0)
115	    {
116	      nxrecorder_release(service->recorder);
117	      service->recorder = NULL;
118	      return ret;
119	    }
120	
121	  ret = nxrecorder_recordinternal(service->recorder,
122	                                  service->config.record_path,
123	                                  AUDIO_FMT_PCM,
124	                                  AUDIO_SERVICE_CAPTURE_CHANNELS,
125	                                  AUDIO_SERVICE_BITS_PER_SAMPLE,
126	                                  AUDIO_SERVICE_SAMPLE_RATE,
127	                                  AUDIO_SERVICE_CAPTURE_CHMAP);
128	  if (ret < 0)
129	    {
130	      nxrecorder_release(service->recorder);
131	      service->recorder = NULL;
132	      return ret;
133	    }
134	
135	  delay.tv_sec = 0;
136	  delay.tv_nsec = AUDIO_SERVICE_POLL_MS * 1000000;
137	  for (elapsed = 0; elapsed < service->config.record_ms;
138	       elapsed += AUDIO_SERVICE_POLL_MS)
139	    {
140	      if (audio_service_cancelled(service, generation))
141	        {
142	          break;
143	        }
144	
145	      nanosleep(&delay, NULL);
146	    }
147	
148	  ret = nxrecorder_stop(service->recorder);
149	  nxrecorder_release(service->recorder);
150	  service->recorder = NULL;
151	  return ret;
152	}
