167	static int audio_service_play(FAR struct audio_service_s *service,
168	                              uint32_t generation,
169	                              uint32_t duration_ms)
170	{
171	  struct nxplayer_status_s status =
172	  {
173	    .state = NXPLAYER_STATE_STARTING,
174	    .result = -EINPROGRESS
175	  };
176	  struct timespec deadline;
177	  uint16_t nxplayer_volume;
178	  uint32_t elapsed;
179	  bool cancelled;
180	  bool timed_out;
181	  int ret;
182	
183	  service->player = nxplayer_create();
184	  if (service->player == NULL)
185	    {
186	      return -ENOMEM;
187	    }
188	
189	  ret = nxplayer_setdevice(service->player,
190	                           service->config.playback_device);
191	  if (ret < 0)
192	    {
193	      nxplayer_release(service->player);
194	      service->player = NULL;
195	      return ret;
196	    }
197	
198	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
199	  nxplayer_volume = audio_service_nxplayer_volume(service->config.volume);
200	  syslog(LOG_INFO,
201	         "routine_mgr: playback volume=%u%% nxplayer_volume=%u\n",
202	         service->config.volume, nxplayer_volume);
203	  ret = nxplayer_setvolume(service->player, nxplayer_volume);
204	  if (ret < 0)
205	    {
206	      nxplayer_release(service->player);
207	      service->player = NULL;
208	      return ret;
209	    }
210	#endif
211	
212	  if (audio_service_cancelled(service, generation))
213	    {
214	      nxplayer_release(service->player);
215	      service->player = NULL;
216	      return -ECANCELED;
217	    }
218	
219	  ret = nxplayer_playraw(service->player, service->config.reply_path,
220	                         AUDIO_FMT_PCM, AUDIO_FMT_UNDEF,
221	                         AUDIO_SERVICE_PLAY_CHANNELS,
222	                         AUDIO_SERVICE_BITS_PER_SAMPLE,
223	                         AUDIO_SERVICE_SAMPLE_RATE,
224	                         AUDIO_SERVICE_PLAY_CHMAP);
225	  if (ret < 0)
226	    {
227	      nxplayer_release(service->player);
228	      service->player = NULL;
229	      return ret;
230	    }
231	
232	  cancelled = false;
233	  timed_out = true;
234	  for (elapsed = 0; elapsed <= duration_ms + 1000;
235	       elapsed += AUDIO_SERVICE_POLL_MS)
236	    {
237	      cancelled = audio_service_cancelled(service, generation);
238	      ret = nxplayer_getstatus(service->player, &status);
239	      if (ret < 0)
240	        {
241	          break;
242	        }
243	
244	      if (cancelled || status.state == NXPLAYER_STATE_IDLE)
245	        {
246	          timed_out = false;
247	          break;
248	        }
249	
250	      clock_gettime(CLOCK_REALTIME, &deadline);
251	      deadline.tv_nsec += AUDIO_SERVICE_POLL_MS * 1000000;
252	      if (deadline.tv_nsec >= 1000000000)
253	        {
254	          deadline.tv_sec++;
255	          deadline.tv_nsec -= 1000000000;
256	        }
257	
258	      pthread_mutex_lock(&service->lock);
259	      if (!service->shutdown_requested &&
260	          service->cancelled_operation != generation)
261	        {
262	          pthread_cond_timedwait(&service->cond, &service->lock, &deadline);
263	        }
264	
265	      pthread_mutex_unlock(&service->lock);
266	    }
267	
268	  if (cancelled || timed_out || status.state != NXPLAYER_STATE_IDLE)
269	    {
270	      syslog(LOG_INFO, "routine_mgr: stopping playback (%s)\n",
271	             cancelled ? "cancelled" : "timeout");
272	      ret = nxplayer_stop(service->player);
273	      if (ret < 0)
274	        {
275	          nxplayer_release(service->player);
276	          service->player = NULL;
277	          return ret;
278	        }
279	    }
280	
281	  ret = nxplayer_getstatus(service->player, &status);
282	  if (ret >= 0)
283	    {
284	      ret = nxplayer_wait(service->player);
285	    }
286	
287	  nxplayer_release(service->player);
288	  service->player = NULL;
289	  if (cancelled)
290	    {
291	      return -ECANCELED;
292	    }
293	
294	  if (timed_out)
295	    {
296	      return -ETIMEDOUT;
297	    }
298	
299	  return ret < 0 ? ret : status.result;
300	}
