302	static int audio_service_sensor_request_spec(
303	  enum audio_service_request_e request, FAR uint32_t *required,
304	  FAR enum voice_reply_type_e *reply_type)
305	{
306	  switch (request)
307	    {
308	      case AUDIO_SERVICE_REQUEST_TEMPERATURE:
309	        if (required != NULL)
310	          {
311	            *required = ENV_METRIC_TEMPERATURE;
312	          }
313	
314	        if (reply_type != NULL)
315	          {
316	            *reply_type = VOICE_REPLY_TEMPERATURE;
317	          }
318	
319	        return OK;
320	
321	      case AUDIO_SERVICE_REQUEST_HUMIDITY:
322	        if (required != NULL)
323	          {
324	            *required = ENV_METRIC_HUMIDITY;
325	          }
326	
327	        if (reply_type != NULL)
328	          {
329	            *reply_type = VOICE_REPLY_HUMIDITY;
330	          }
331	
332	        return OK;
333	
334	      case AUDIO_SERVICE_REQUEST_BH1750:
335	        if (required != NULL)
336	          {
337	            *required = ENV_METRIC_LIGHT;
338	          }
339	
340	        if (reply_type != NULL)
341	          {
342	            *reply_type = VOICE_REPLY_BH1750;
343	          }
344	
345	        return OK;
346	
347	      case AUDIO_SERVICE_REQUEST_SGP30:
348	        if (required != NULL)
349	          {
350	            *required = ENV_METRIC_ECO2 | ENV_METRIC_TVOC;
351	          }
352	
353	        if (reply_type != NULL)
354	          {
355	            *reply_type = VOICE_REPLY_SGP30;
356	          }
357	
358	        return OK;
359	
360	      default:
361	        return -EINVAL;
362	    }
363	}
