365	static void audio_service_process(
366	  FAR struct audio_service_s *service,
367	  FAR const struct audio_service_operation_s *operation)
368	{
369	  struct audio_service_cancel_context_s cancel_context;
370	  struct voice_recognition_result_s recognition;
371	  struct voice_reply_values_s values;
372	  enum audio_service_request_e request;
373	  uint32_t generation;
374	  enum voice_reply_type_e reply_type;
375	  uint32_t duration_ms;
376	  uint32_t required;
377	  int ret;
378	
379	  generation = operation->id;
380	  request = operation->request;
381	  values = operation->values;
382	  cancel_context.service = service;
383	  cancel_context.operation = generation;
384	
385	  if (request != AUDIO_SERVICE_REQUEST_QUERY)
386	    {
387	      if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
388	        {
389	          required = 0;
390	          reply_type = VOICE_REPLY_SCHEDULE_REMINDER;
391	          ret = OK;
392	        }
393	      else
394	        {
395	          ret = audio_service_sensor_request_spec(request, &required,
396	                                                  &reply_type);
397	        }
398	
399	      if (ret < 0)
400	        {
401	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
402	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
403	          return;
404	        }
405	
406	      audio_service_publish(service, generation, AUDIO_SERVICE_PROCESSING,
407	                            AUDIO_SERVICE_ERROR_NONE);
408	      ret = voice_reply_build_cancelable(service->config.asset_dir,
409	                                         service->config.reply_path,
410	                                         reply_type, &values, &duration_ms,
411	                                         audio_service_reply_cancel,
412	                                         &cancel_context);
413	      if (ret < 0)
414	        {
415	          if (ret == -ECANCELED ||
416	              audio_service_cancelled(service, generation))
417	            {
418	              audio_service_finish_operation(service, generation,
419	                                        AUDIO_SERVICE_OUTCOME_CANCELLED);
420	              return;
421	            }
422	
423	          syslog(LOG_ERR,
424	                 "routine_mgr: sensor reply request=%u build failed: %d\n",
425	                 request, ret);
426	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
427	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
428	          return;
429	        }
430	
431	      if (audio_service_cancelled(service, generation))
432	        {
433	          unlink(service->config.reply_path);
434	          audio_service_finish_operation(service, generation,
435	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
436	          return;
437	        }
438	
439	      audio_service_publish(service, generation, AUDIO_SERVICE_SPEAKING,
440	                            AUDIO_SERVICE_ERROR_NONE);
441	      ret = audio_service_play(service, generation, duration_ms);
442	      unlink(service->config.reply_path);
443	      if (audio_service_cancelled(service, generation))
444	        {
445	          audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
446	          return;
447	        }
448	
449	      if (ret < 0)
450	        {
451	          if (ret == -ECANCELED)
452	            {
453	              audio_service_finish_operation(service, generation,
454	                                        AUDIO_SERVICE_OUTCOME_CANCELLED);
455	              return;
456	            }
457	
458	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
459	                                AUDIO_SERVICE_ERROR_PLAYBACK);
460	          return;
461	        }
462	
463	      audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
464	      return;
465	    }
466	
467	  audio_service_publish(service, generation, AUDIO_SERVICE_LISTENING,
468	                        AUDIO_SERVICE_ERROR_NONE);
469	  ret = audio_service_capture(service, generation);
470	  if (audio_service_cancelled(service, generation))
471	    {
472	      unlink(service->config.record_path);
473	      audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
474	      return;
475	    }
476	
477	  if (ret < 0)
478	    {
479	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
480	                            AUDIO_SERVICE_ERROR_CAPTURE);
481	      return;
482	    }
483	
484	  audio_service_publish(service, generation, AUDIO_SERVICE_PROCESSING,
485	                        AUDIO_SERVICE_ERROR_NONE);
486	  ret = voice_recognizer_demo_recognize(service->config.record_path,
487	                                        &recognition);
488	  unlink(service->config.record_path);
489	  if (audio_service_cancelled(service, generation))
490	    {
491	      audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
492	      return;
493	    }
494	
495	  if (ret < 0 || recognition.command != VOICE_COMMAND_QUERY_TEMPERATURE)
496	    {
497	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
498	                            AUDIO_SERVICE_ERROR_NO_VOICE);
499	      return;
500	    }
501	
502	  pthread_mutex_lock(&service->lock);
503	  service->recognition_score = recognition.score;
504	  service->semantic_verified = recognition.semantic_verified;
505	  service->has_result = true;
506	  service->sequence++;
507	  pthread_mutex_unlock(&service->lock);
508	
509	  ret = voice_reply_build_cancelable(service->config.asset_dir,
510	                                     service->config.reply_path,
511	                                     VOICE_REPLY_TEMPERATURE, &values,
512	                                     &duration_ms, audio_service_reply_cancel,
513	                                     &cancel_context);
514	  if (ret < 0)
515	    {
516	      if (ret == -ECANCELED || audio_service_cancelled(service, generation))
517	        {
518	          audio_service_finish_operation(service, generation,
519	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
520	          return;
521	        }
522	
523	      syslog(LOG_ERR, "routine_mgr: failed to build voice reply: %d\n", ret);
524	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
525	                            AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
526	      return;
527	    }
528	
529	  if (audio_service_cancelled(service, generation))
530	    {
531	      unlink(service->config.reply_path);
532	      audio_service_finish_operation(service, generation,
533	                                AUDIO_SERVICE_OUTCOME_CANCELLED);
534	      return;
535	    }
536	
537	  audio_service_publish(service, generation, AUDIO_SERVICE_SPEAKING,
538	                        AUDIO_SERVICE_ERROR_NONE);
539	  ret = audio_service_play(service, generation, duration_ms);
540	  unlink(service->config.reply_path);
541	  if (audio_service_cancelled(service, generation))
542	    {
543	      audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
544	      return;
545	    }
546	
547	  if (ret < 0)
548	    {
549	      if (ret == -ECANCELED)
550	        {
551	          audio_service_finish_operation(service, generation,
552	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
553	          return;
554	        }
555	
556	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
557	                            AUDIO_SERVICE_ERROR_PLAYBACK);
558	      return;
559	    }
560	
561	  audio_service_finish_operation(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
562	}
