564	static void audio_service_claim_locked(FAR struct audio_service_s *service)
565	{
566	  FAR struct audio_service_operation_s *operation = &service->active;
567	
568	  memset(operation, 0, sizeof(*operation));
569	  if (service->reminder_count > 0)
570	    {
571	      operation->reminder = service->reminder_queue[service->reminder_head];
572	      service->reminder_head =
573	        (service->reminder_head + 1) % AUDIO_SERVICE_REMINDER_MAX;
574	      service->reminder_count--;
575	      operation->request = AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER;
576	      operation->values = service->sensor.values;
577	      operation->values.schedule_text_id = operation->reminder.text_id;
578	      operation->values.schedule_hour = operation->reminder.hour;
579	      operation->values.schedule_minute = operation->reminder.minute;
580	      service->current_reminder = operation->reminder;
581	      service->generation++;
582	      operation->id = service->generation;
583	    }
584	  else
585	    {
586	      *operation = service->pending_operation;
587	      memset(&service->pending_operation, 0,
588	             sizeof(service->pending_operation));
589	      service->start_requested = false;
590	    }
591	
592	  service->worker_active = true;
593	  service->active_operation = operation->id;
594	  service->request = operation->request;
595	  service->state = operation->request == AUDIO_SERVICE_REQUEST_QUERY ?
596	                   AUDIO_SERVICE_LISTENING : AUDIO_SERVICE_PROCESSING;
597	  service->error = AUDIO_SERVICE_ERROR_NONE;
598	  service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
599	  service->sequence++;
600	  syslog(LOG_INFO,
601	         "routine_mgr: audio claim op=%lu request=%u reminder=%u/%lu pending=%u\n",
602	         (unsigned long)operation->id, operation->request,
603	         operation->reminder.schedule_id,
604	         (unsigned long)operation->reminder.sequence,
605	         service->reminder_count);
606	}
607	
608	static FAR void *audio_service_thread(FAR void *arg)
609	{
610	  FAR struct audio_service_s *service = arg;
611	
612	  while (true)
613	    {
614	      struct audio_service_operation_s operation;
615	
616	      pthread_mutex_lock(&service->lock);
617	      while (!service->start_requested && service->reminder_count == 0 &&
618	             !service->shutdown_requested)
619	        {
620	          service->worker_active = false;
621	          service->active_operation = 0;
622	          memset(&service->active, 0, sizeof(service->active));
623	          memset(&service->current_reminder, 0,
624	                 sizeof(service->current_reminder));
625	          service->request = AUDIO_SERVICE_REQUEST_NONE;
626	          if (service->state != AUDIO_SERVICE_IDLE)
627	            {
628	              service->state = AUDIO_SERVICE_IDLE;
629	              service->sequence++;
630	            }
631	
632	          pthread_cond_wait(&service->cond, &service->lock);
633	        }
634	
635	      if (service->shutdown_requested)
636	        {
637	          pthread_mutex_unlock(&service->lock);
638	          break;
639	        }
640	
641	      /* Due reminders have priority immediately after the current operation.
642	       * The transition is atomic and never exposes an intermediate IDLE.
643	       */
644	
645	      audio_service_claim_locked(service);
646	      operation = service->active;
647	      pthread_mutex_unlock(&service->lock);
648	      audio_service_process(service, &operation);
649	
650	      pthread_mutex_lock(&service->lock);
651	      if (service->active_operation == operation.id)
652	        {
653	          syslog(LOG_INFO,
654	                 "routine_mgr: audio finish op=%lu outcome=%u error=%u pending=%u\n",
655	                 (unsigned long)operation.id, service->outcome,
656	                 service->error, service->reminder_count);
657	          if (service->cancelled_operation == operation.id)
658	            {
659	              service->cancelled_operation = 0;
660	            }
661	          else if (operation.request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER &&
662	                   service->outcome == AUDIO_SERVICE_OUTCOME_FAILED &&
663	                   operation.reminder.attempts == 0 &&
664	                   service->reminder_count < AUDIO_SERVICE_REMINDER_MAX)
665	            {
666	              struct audio_service_reminder_s queue[AUDIO_SERVICE_REMINDER_MAX];
667	              uint8_t i;
668	
669	              operation.reminder.attempts = 1;
670	              queue[0] = operation.reminder;
671	              for (i = 0; i < service->reminder_count; i++)
672	                {
673	                  uint8_t index = (service->reminder_head + i) %
674	                                  AUDIO_SERVICE_REMINDER_MAX;
675	                  queue[i + 1] = service->reminder_queue[index];
676	                }
677	
678	              memcpy(service->reminder_queue, queue,
679	                     (service->reminder_count + 1) * sizeof(queue[0]));
680	              service->reminder_head = 0;
681	              service->reminder_count++;
682	              syslog(LOG_WARNING,
683	                     "routine_mgr: retry reminder=%u/%lu error=%u\n",
684	                     operation.reminder.schedule_id,
685	                     (unsigned long)operation.reminder.sequence,
686	                     service->error);
687	            }
688	
689	          service->worker_active = false;
690	          service->active_operation = 0;
691	          memset(&service->active, 0, sizeof(service->active));
692	          service->sequence++;
693	        }
694	
695	      pthread_mutex_unlock(&service->lock);
696	    }
697	
698	  return NULL;
699	}
