701	int audio_service_initialize(FAR struct audio_service_s *service,
702	                             FAR const struct audio_service_config_s *config)
703	{
704	  struct sched_param sched;
705	  pthread_attr_t attr;
706	  int ret;
707	
708	  if (service == NULL || config == NULL || config->capture_device == NULL ||
709	      config->playback_device == NULL || config->record_path == NULL ||
710	      config->reply_path == NULL || config->asset_dir == NULL ||
711	      config->record_ms == 0 || config->volume < 1 || config->volume > 100)
712	    {
713	      return -EINVAL;
714	    }
715	
716	  memset(service, 0, sizeof(*service));
717	  service->config = *config;
718	  service->state = AUDIO_SERVICE_IDLE;
719	  ret = pthread_mutex_init(&service->lock, NULL);
720	  if (ret != 0)
721	    {
722	      return -ret;
723	    }
724	
725	  ret = pthread_cond_init(&service->cond, NULL);
726	  if (ret != 0)
727	    {
728	      pthread_mutex_destroy(&service->lock);
729	      return -ret;
730	    }
731	
732	  pthread_attr_init(&attr);
733	  if (config->stack_size > 0)
734	    {
735	      pthread_attr_setstacksize(&attr, config->stack_size);
736	    }
737	
738	  if (config->priority > 0)
739	    {
740	      memset(&sched, 0, sizeof(sched));
741	      sched.sched_priority = config->priority;
742	      pthread_attr_setschedparam(&attr, &sched);
743	    }
744	
745	  ret = pthread_create(&service->thread, &attr, audio_service_thread, service);
746	  pthread_attr_destroy(&attr);
747	  if (ret != 0)
748	    {
749	      pthread_cond_destroy(&service->cond);
750	      pthread_mutex_destroy(&service->lock);
751	      return -ret;
752	    }
753	
754	  service->thread_created = true;
755	  service->initialized = true;
756	  return OK;
757	}
