759	int audio_service_begin(FAR struct audio_service_s *service)
760	{
761	  if (service == NULL || !service->initialized)
762	    {
763	      return -EINVAL;
764	    }
765	
766	  pthread_mutex_lock(&service->lock);
767	  if (service->worker_active || service->start_requested ||
768	      service->reminder_count > 0)
769	    {
770	      pthread_mutex_unlock(&service->lock);
771	      return -EBUSY;
772	    }
773	
774	  service->generation++;
775	  memset(&service->pending_operation, 0,
776	         sizeof(service->pending_operation));
777	  service->pending_operation.id = service->generation;
778	  service->pending_operation.request = AUDIO_SERVICE_REQUEST_QUERY;
779	  service->pending_operation.values = service->sensor.values;
780	  service->request = AUDIO_SERVICE_REQUEST_QUERY;
781	  service->start_requested = true;
782	  service->cancelled_operation = 0;
783	  service->state = AUDIO_SERVICE_LISTENING;
784	  service->error = AUDIO_SERVICE_ERROR_NONE;
785	  service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
786	  service->has_result = false;
787	  service->recognition_score = 0;
788	  service->semantic_verified = false;
789	  service->sequence++;
790	  pthread_cond_signal(&service->cond);
791	  pthread_mutex_unlock(&service->lock);
792	  return OK;
793	}
