795	int audio_service_play_sensor(FAR struct audio_service_s *service,
796	                              enum audio_service_request_e request)
797	{
798	  uint32_t required;
799	
800	  if (service == NULL || !service->initialized ||
801	      audio_service_sensor_request_spec(request, &required, NULL) < 0)
802	    {
803	      return -EINVAL;
804	    }
805	
806	  pthread_mutex_lock(&service->lock);
807	  if (service->worker_active || service->start_requested ||
