60	static FAR void *async_read(FAR void *arg)
61	{
62	  FAR struct ymodem_priv_s *priv = arg;
63	
64	  pthread_mutex_lock(&priv->mutex);
65	  while (priv->exited == false)
66	    {
67	      FAR uint8_t *buffer;
68	      ssize_t ret = 0;
69	      size_t size;
70	
71	      if (priv->fd > 0)
72	        {
73	          buffer = circbuf_get_writeptr(&priv->circ, &size);
74	          ret = read(priv->fd, buffer, size);
75	          if (ret < 0)
76	            {
77	              break;
78	            }
79	
80	          circbuf_writecommit(&priv->circ, ret);
81	        }
82	
83	      if (circbuf_is_full(&priv->circ) || priv->fd <= 0 || ret == 0)
84	        {
85	          pthread_cond_wait(&priv->cond, &priv->mutex);
86	        }
87	    }
88	
89	  pthread_mutex_unlock(&priv->mutex);
90	  return NULL;
91	}
