93	static int read_data(FAR struct ymodem_priv_s *priv,
94	                     FAR uint8_t *data, size_t size)
95	{
96	  ssize_t i = 0;
97	
98	  if (priv->buffersize)
99	    {
100	      pthread_mutex_lock(&priv->mutex);
101	      while (i < size)
102	        {
103	          ssize_t ret = circbuf_read(&priv->circ, data + i, size - i);
104	
105	          if (ret < 0)
106	            {
107	              pthread_mutex_unlock(&priv->mutex);
108	              return ret;
109	            }
110	
111	          if (ret == 0)
112	            {
113	              ret = read(priv->fd, data + i, size - i);
114	              if (ret < 0)
115	                {
116	                  pthread_mutex_unlock(&priv->mutex);
117	                  return -errno;
118	                }
119	            }
120	
121	          i += ret;
122	        }
123	
124	      pthread_cond_signal(&priv->cond);
125	      pthread_mutex_unlock(&priv->mutex);
126	    }
127	  else
128	    {
129	      while (i < size)
130	        {
131	          ssize_t ret = read(priv->fd, data + i, size - i);
132	
133	          if (ret < 0)
134	            {
135	              return -errno;
136	            }
137	
138	          i += ret;
139	        }
140	    }
141	
142	  return 0;
143	}
