1035	/****************************************************************************
1036	 * Name: nxrecorder_recordinteral
1037	 *
1038	 *   nxrecorder_recordinternal() tries to record audio file using the Audio
1039	 *   system. If a device is specified, it will try to use that
1040	 *   device.
1041	 * Input:
1042	 *   precorder  Pointer to the initialized MRecorder context
1043	 *   pfilename  Pointer to the filename to record
1044	 *   nchannels  channel num
1045	 *   bpsampe    bit width
1046	 *   samprate   sample rate
1047	 *   chmap      channel map
1048	 *
1049	 * Returns:
1050	 *   OK         File is being recorded
1051	 *   -EBUSY     The media device is busy
1052	 *   -ENOSYS    The media file is an unsupported type
1053	 *   -ENODEV    No audio device suitable to record the media type
1054	 *   -ENOENT    The media file was not found
1055	 *
1056	 ****************************************************************************/
1057	
1058	int nxrecorder_recordinternal(FAR struct nxrecorder_s *precorder,
1059	                              FAR const char *pfilename, int filefmt,
1060	                              uint8_t nchannels, uint8_t bpsamp,
1061	                              uint32_t samprate, uint8_t chmap)
1062	{
1063	  struct mq_attr           attr;
1064	  struct sched_param       sparam;
1065	  pthread_attr_t           tattr;
1066	  struct audio_caps_desc_s cap_desc;
1067	  struct ap_buffer_info_s  buf_info;
1068	  struct audio_caps_s      caps;
1069	  int                      min_channels;
1070	  int                      ret;
1071	  int                      subfmt = AUDIO_FMT_UNDEF;
1072	  int                      index;
1073	
1074	  DEBUGASSERT(precorder != NULL);
1075	  DEBUGASSERT(pfilename != NULL);
1076	
1077	  if (precorder->state != NXRECORDER_STATE_IDLE)
1078	    {
1079	      return -EBUSY;
1080	    }
1081	
1082	  audinfo("==============================\n");
1083	  audinfo("Recording file %s\n", pfilename);
1084	  audinfo("==============================\n");
1085	
1086	  /* Test that the specified file exists */
1087	
1088	  if ((precorder->fd = open(pfilename, O_WRONLY | O_CREAT | O_TRUNC,
1089	                            0666)) == -1)
1090	    {
1091	      /* File not found.  Test if its in the mediadir */
1092	
1093	      auderr("ERROR: Could not open %s\n", pfilename);
1094	      return -ENOENT;
1095	    }
1096	
1097	  if (filefmt == AUDIO_FMT_UNDEF)
1098	    {
1099	      filefmt = nxrecorder_fmtfromext(precorder, pfilename, &subfmt);
1100	    }
1101	
1102	  /* Test if we determined the file format */
1103	
1104	  if (filefmt == AUDIO_FMT_UNDEF)
1105	    {
1106	      /* Hmmm, it's some unknown / unsupported type */
1107	
1108	      auderr("ERROR: Unsupported format: %d\n", filefmt);
1109	      ret = -ENOSYS;
1110	      goto err_out_nodev;
1111	    }
1112	
1113	  /* Try to open the device */
1114	
1115	  ret = nxrecorder_opendevice(precorder, filefmt, subfmt);
1116	  if (ret < 0)
1117	    {
1118	      /* Error opening the device */
1119	
1120	      auderr("ERROR: nxrecorder_opendevice failed: %d\n", ret);
1121	      goto err_out_nodev;
1122	    }
1123	
1124	  for (index = 0; index < sizeof(g_enc_ops) / sizeof(g_enc_ops[0]); index++)
1125	    {
1126	      if (g_enc_ops[index].format == filefmt)
1127	        {
1128	          precorder->ops = &g_enc_ops[index];
1129	          break;
1130	        }
1131	    }
1132	
1133	  if (!precorder->ops)
1134	    {
1135	      ret = -ENOSYS;
1136	      goto err_out;
1137	    }
1138	
1139	  if (precorder->ops->pre_write)
1140	    {
1141	      ret = precorder->ops->pre_write(precorder->fd,
1142	                                      samprate, nchannels, bpsamp);
1143	      if (ret < 0)
1144	        {
1145	          goto err_out;
1146	        }
1147	    }
1148	
1149	  /* Try to reserve the device */
1150	
1151	#ifdef CONFIG_AUDIO_MULTI_SESSION
1152	  ret = ioctl(precorder->dev_fd, AUDIOIOC_RESERVE,
1153	              (uintptr_t)&precorder->session);
1154	#else
1155	  ret = ioctl(precorder->dev_fd, AUDIOIOC_RESERVE, 0);
1156	#endif
1157	  if (ret < 0)
1158	    {
1159	      /* Device is busy or error */
1160	
1161	      auderr("ERROR: Failed to reserve device: %d\n", ret);
1162	      ret = -errno;
1163	      goto err_out;
1164	    }
1165	
1166	  caps.ac_len = sizeof(caps);
1167	  caps.ac_type = AUDIO_TYPE_INPUT;
1168	  caps.ac_subtype = AUDIO_TYPE_QUERY;
1169	
1170	  if (ioctl(precorder->dev_fd, AUDIOIOC_GETCAPS,
1171	      (unsigned long)&caps) == caps.ac_len)
1172	    {
1173	      min_channels = caps.ac_channels >> 4;
1174	
1175	      if (min_channels != 0 && nchannels < min_channels)
1176	        {
1177	          ret = -EINVAL;
1178	          goto err_out;
1179	        }
1180	    }
1181	
1182	#ifdef CONFIG_AUDIO_MULTI_SESSION
1183	  cap_desc.session = precorder->session;
1184	#endif
1185	  cap_desc.caps.ac_len = sizeof(struct audio_caps_s);
1186	  cap_desc.caps.ac_type = AUDIO_TYPE_INPUT;
1187	  cap_desc.caps.ac_channels = nchannels ? nchannels : 2;
1188	  cap_desc.caps.ac_chmap    = chmap;
1189	  cap_desc.caps.ac_controls.hw[0] = samprate ? samprate : 48000;
1190	  cap_desc.caps.ac_controls.b[3] = samprate >> 16;
1191	  cap_desc.caps.ac_controls.b[2]  = bpsamp ? bpsamp : 16;
1192	  cap_desc.caps.ac_subtype        = filefmt;
1193	  ret = ioctl(precorder->dev_fd, AUDIOIOC_CONFIGURE,
1194	              (uintptr_t)&cap_desc);
1195	  if (ret < 0)
1196	    {
1197	      ret = -errno;
1198	      goto err_out;
1199	    }
1200	
1201	  /* Query the audio device for its preferred buffer count */
1202	
1203	  if (ioctl(precorder->dev_fd, AUDIOIOC_GETBUFFERINFO,
1204	            (uintptr_t)&buf_info) != OK)
1205	    {
1206	      /* Driver doesn't report its buffer size.  Use our default. */
1207	
1208	      buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
1209	    }

