      kws_capture_id_valid("../speaker") ||
      kws_capture_isqrt(0) != 0 || kws_capture_isqrt(14400) != 120)
    {
      return -EINVAL;
    }

  options.label = "temperature";
  if (kws_capture_validate_options(&options) >= 0)
    {
      return -EINVAL;
    }

  options.label = "query_temperature";
  options.record_ms = 999;
  if (kws_capture_validate_options(&options) >= 0)
    {
      return -EINVAL;
    }

  return OK;
}

