static uint64_t kws_capture_hash_token(uint64_t hash, FAR const char *token)
{
  while (*token != '\0')
    {
      hash ^= (uint8_t)*token++;
      hash *= UINT64_C(1099511628211);
    }

  hash ^= 0xff;
  hash *= UINT64_C(1099511628211);
  return hash;
}

