static int kws_capture_publish_pair(FAR const char *pcm_part,
                                    FAR const char *json_part,
                                    FAR const char *pcm_path,
                                    FAR const char *json_path)
{
  int ret;

  if (link(pcm_part, pcm_path) < 0)
    {
      return -errno;
    }

  if (link(json_part, json_path) < 0)
    {
      ret = -errno;
      unlink(pcm_path);
      return ret;
    }

  if (unlink(pcm_part) < 0 || unlink(json_part) < 0)
    {
      return -errno;
    }

  return OK;
}

